// Parse /update message into structured data
const rawText = ($json.text || '').replace(/\s*\*?Sent using\*?\s*Claude\s*$/i, '');
const channel = $json.channel || '';
const ts = $json.ts || '';
const user = $json.user || '';

const lines = rawText.trim().split('\n');

// First line: /update [App]
const firstLine = lines[0].trim();
const match = firstLine.match(/^\/update\s+(.+)$/i);
if (!match) {
  return { json: { error: 'Invalid /update format', rawText: rawText, channel, ts } };
}

const appName = match[1].trim().toLowerCase();
const fields = {};

// Parse key: value pairs from remaining lines
for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  const colonIdx = line.indexOf(':');
  if (colonIdx > 0) {
    const key = line.substring(0, colonIdx).trim().toLowerCase();
    const value = line.substring(colonIdx + 1).trim();
    if (value) fields[key] = value;
  }
}

return {
  json: {
    appName,
    fields,
    channel,
    messageTs: ts,
    userId: user,
    clientName: fields.client || '',
    valid: !!fields.client
  }
};

// SmartSuite Sync Agent — Lookup & Update
const SS_TOKEN = '<REDACTED>';
const SS_ACCOUNT = '52739';
const SS_BASE = 'https://app.smartsuite.com/api/v1';

const APP_MAP = {
  tasks: '69ce67b3fec5b91842ebaf03',
  campaigns: '69ce678977bf866e34b46f68',
  onboarding: '69db909cd9114601cccb2b57',
  pipeline: '6908636826cfbf4238a34f31',
  optimization: '69ce67e01cc0855f89fee02e',
  finance: '69cee1623a5dd7f2078e4d93',
  clients: '69ce5f18cb8a07430bfee02d'
};

const TITLE_APPS = ['onboarding', 'pipeline', 'clients'];

const STATUS_MAPS = {
  tasks: { 'to do': 'To Do', 'in progress': 'In Progress', 'blocked': 'Blocked', 'done': 'Done' },
  campaigns: { 'draft': 'Draft', 'qa ready': 'QA Ready', 'live': 'Live', 'paused': 'Paused', 'cut': 'Cut', 'completed': 'Completed' },
  clients: { 'onboarding': 'Onboarding', 'active': 'Active', 'paused': 'Paused', 'churned': 'Churned' },
  finance_payment: { 'paid': 'Paid', 'unpaid': 'Unpaid', 'overdue': 'Overdue', 'n/a': 'N/A' },
  pipeline: {
    'conversation - positive': 'Conversation - Positive',
    'follow up / reschedule': 'Follow Up / Reschedule',
    'booked': 'Booked', 'no show': 'No Show', 'cancelled': 'Cancelled',
    'proposal - decision - pending': 'Proposal - Decision - Pending',
    'ghosted': 'Ghosted', 'signed - invoice sent': 'Signed - Invoice Sent',
    'won': 'Won', 'lost': 'Lost'
  },
  optimization_decision: {
    'keep running': 'Keep Running', 'cut': 'Cut', 'retarget test': 'Retarget Test',
    'lead ad candidate': 'Lead Ad Candidate', 'swap creative': 'Swap Creative'
  }
};

const OB_STEP_MAP = {
  'business portfolio access': 'step_business_portfolio_access',
  'ad account visible': 'step_ad_account_visible',
  'facebook page confirmed': 'step_facebook_page_confirmed',
  'instagram connected': 'step_instagram_connected',
  'meta ads app installed': 'step_meta_ads_app_installed',
  'leads access confirmed': 'step_leads_access_confirmed',
  'lead notifications set': 'step_lead_notifications_set',
  'lead centre to crm': 'step_lead_centre_to_crm',
  'lead destination confirmed': 'step_lead_destination_confirmed',
  'fb lead centre connected': 'step_fb_lead_centre_connected',
  'video brief sent': 'step_video_brief_sent',
  'videos received': 'step_videos_received',
  'videos edited': 'step_videos_edited',
  'approved videos exist': 'step_approved_videos_exist',
  'campaign built': 'step_campaign_built',
  'qa passed': 'step_qa_passed',
  'campaign launched': 'step_campaign_launched',
  'launch notification sent': 'step_launch_notification_sent',
  'onboarding complete': 'step_onboarding_complete'
};

const OB_STATUS_MAP = { 'not started': 1, 'in progress': 2, 'complete': 3 };

async function ssReq(method, path, body) {
  const opts = {
    method,
    url: `${SS_BASE}${path}`,
    headers: {
      Authorization: `Token ${SS_TOKEN}`,
      'Account-Id': SS_ACCOUNT,
      'Content-Type': 'application/json'
    },
    json: true
  };
  if (body) opts.body = body;
  return await this.helpers.httpRequest(opts);
}

try {
  const { appName, fields, channel, messageTs, clientName } = $json;
  const appId = APP_MAP[appName];
  if (!appId) return { json: { success: false, error: `Unknown app: ${appName}`, channel, messageTs } };
  if (!clientName) return { json: { success: false, error: "No client name", channel, messageTs } };

  // Find client record
  let clientRecordId = null;
  const cs = await ssReq.call(this, 'POST', `/applications/${APP_MAP.clients}/records/list/`, {
    filter: { operator: 'and', fields: [{ field: 'title', comparison: 'is', value: clientName }] },
    limit: 1
  });
  if (cs.items && cs.items.length > 0) clientRecordId = cs.items[0].id;

  // Find target record
  let sf;
  if (TITLE_APPS.includes(appName)) {
    sf = { filter: { operator: 'and', fields: [{ field: 'title', comparison: 'is', value: clientName }] }, limit: 1 };
  } else if (clientRecordId) {
    sf = { filter: { operator: 'and', fields: [{ field: 'client', comparison: 'has_any_of', value: [clientRecordId] }] }, limit: 5 };
  } else {
    return { json: { success: false, error: `Client "${clientName}" not found`, channel, messageTs } };
  }

  if (appName === 'tasks' && fields.task) {
    sf.filter.filters.push({ field: 'title', comparison: 'contains', value: fields.task });
    sf.limit = 1;
  }
  if (appName === 'campaigns' && fields.campaign) {
    sf.filter.filters.push({ field: 'title', comparison: 'contains', value: fields.campaign });
    sf.limit = 1;
  }

  const ts = await ssReq.call(this, 'POST', `/applications/${appId}/records/list/`, sf);
  if (!ts.items || ts.items.length === 0)
    return { json: { success: false, error: `No ${appName} record for "${clientName}"`, channel, messageTs } };
  const rec = ts.items[0];

  // Build update payload
  const up = {};
  switch (appName) {
    case 'tasks': {
      if (fields.status) { const m = STATUS_MAPS.tasks[fields.status.toLowerCase()]; if (m) up.status = m; }
      if (fields.notes) up.description = (rec.description||'') + '\n\n[Slack] ' + fields.notes;
      break;
    }
    case 'campaigns': {
      const a = (fields.action||'').toLowerCase();
      if (a === 'build complete') up.status = 'Draft';
      else if (a === 'qa ready') up.status = 'QA Ready';
      else if (a === 'launched') up.status = 'Live';
      else if (a === 'paused') up.status = 'Paused';
      if (fields.notes) up.build_sop_reference = (rec.build_sop_reference||'') + '\n\n[Slack] ' + fields.notes;
      break;
    }
    case 'onboarding': {
      if (fields.step && fields.status) {
        const slug = OB_STEP_MAP[fields.step.toLowerCase()];
        const val = OB_STATUS_MAP[fields.status.toLowerCase()];
        if (slug && val) up[slug] = val;
      }
      break;
    }
    case 'pipeline': {
      { const sv = fields.stage || fields['deal stage'] || fields['deal_stage']; if (sv) { const m = STATUS_MAPS.pipeline[sv.toLowerCase()]; if (m) up.deal_stage = m; }}
      if (fields.notes) up.notes = (rec.notes||'') + '\n\n[Slack] ' + fields.notes;
      break;
    }
    case 'optimization': {
      if ((fields.action||'').toLowerCase() === 'review complete' && fields.decision) {
        const m = STATUS_MAPS.optimization_decision[fields.decision.toLowerCase()];
        if (m) up.decision = m;
      }
      break;
    }
    case 'finance': {
      const fa = (fields.action||'').toLowerCase();
      if (fa === 'payment received') up.payment_status = 'Paid';
      else if (fa === 'invoice sent') up.payment_status = 'Unpaid';
      else if (fa === 'payment overdue') up.payment_status = 'Overdue';
      if (fields.amount) { const amt = parseFloat(fields.amount.replace(/[^0-9.]/g,'')); if (!isNaN(amt)) up.amount = amt; }
      if (fields.notes) up.notes = (rec.notes||'') + '\n\n[Slack] ' + fields.notes;
      break;
    }
    case 'clients': {
      if ((fields.action||'').toLowerCase() === 'info update' && fields.field && fields.value) {
        const fm = { status:'status', niche:'priority', market:'market_region', 'contact name':'contact_name', 'contact email':'contact_email', 'contact phone':'contact_phone', 'facebook page url':'facebook_page_url', 'instagram handle':'instagram_handle', 'ad account id':'client_ad_account_id' };
        const s = fm[fields.field.toLowerCase()];
        if (s) { if (s==='status') { const m=STATUS_MAPS.clients[fields.value.toLowerCase()]; if(m) up[s]=m; } else up[s]=fields.value; }
      }
      if (fields.notes) up.notes = (rec.notes||'') + '\n\n[Slack] ' + fields.notes;
      break;
    }
  }

  if (Object.keys(up).length === 0)
    return { json: { success: false, error: 'No valid fields to update', channel, messageTs, appName } };

  await ssReq.call(this, 'PATCH', `/applications/${appId}/records/${rec.id}/`, up);
  return { json: { success: true, appName, recordId: rec.id, recordTitle: rec.title||"", fieldsUpdated: Object.keys(up), channel, messageTs } };
} catch (err) {
  return { json: { success: false, error: err.message||String(err), channel: $json.channel, messageTs: $json.messageTs } };
}

